    if (fread(buf, 1, sz, f) != (size_t)sz) { fprintf(stderr, "read error\n"); return 1; }
    buf[sz] = 0; fclose(f);
    cJSON* root = cJSON_Parse(buf);
    if (!root) { fprintf(stderr, "json parse error\n"); return 1; }

    int n_w1,n_b1,n_w2,n_b2,n_w3,n_b3;
    double* w1 = load_array(root, "input_layer.weight", &n_w1);
    double* b1 = load_array(root, "input_layer.bias", &n_b1);
    double* w2 = load_array(root, "hidden_layer.weight", &n_w2);
    double* b2 = load_array(root, "hidden_layer.bias", &n_b2);
    double* w3 = load_array(root, "output_layer.weight", &n_w3);
    double* b3 = load_array(root, "output_layer.bias", &n_b3);

    unsigned char* img = NULL; unsigned w, h;
    unsigned err = lodepng_decode32_file(&img, &w, &h, argv[2]);
    if (err) { fprintf(stderr, "png error %s\n", lodepng_error_text(err)); return 1; }
    int N = (int)(w * h);
    if (N != n_w1) { fprintf(stderr, "expected %d pixels, got %d\n", n_w1, N); return 1; }
    double* x = (double*)malloc(sizeof(double)*N);
    for (int i = 0; i < N; i++) x[i] = img[i*4] / 255.0;

    double* h1 = (double*)malloc(sizeof(double)*n_b1);
    for (int o = 0; o < n_b1; o++) { double s = b1[o]; for (int c = 0; c < N; c++) s += w1[o*N + c] * x[c]; h1[o] = s > 0 ? s : 0; }
    double* h2 = (double*)malloc(sizeof(double)*n_b2);
    for (int o = 0; o < n_b2; o++) { double s = b2[o]; for (int c = 0; c < n_b1; c++) s += w2[o*n_b1 + c] * h1[c]; h2[o] = s > 0 ? s : 0; }
    double* h3 = (double*)malloc(sizeof(double)*n_b3);
